import{_ as s,a0 as u,w as a,s as i,I as p,x as e,a1 as o,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"將 Tuleap 用於軟件項目管理 | LCTT x X-CMD","titleTemplate":false,"description":"將 Tuleap 用於軟件項目管理 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將 Tuleap 用於軟件項目管理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將 Tuleap 用於軟件項目管理 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170119 Get to know Tuleap for project management","title":"將 Tuleap 用於軟件項目管理","tag":"201703","desc":""},"relativePath":"201703/20170119 Get to know Tuleap for project management.md","filePath":"[post].md"}'),T={name:"201703/20170119 Get to know Tuleap for project management.md"};function m(g,t,f,d,k,w){const l=u("Link");return a(),i("div",null,[t[24]||(t[24]=p("h1",{id:"將-tuleap-用於軟件項目管理",tabindex:"-1"},[e("將 Tuleap 用於軟件項目管理 "),p("a",{class:"header-anchor",href:"#將-tuleap-用於軟件項目管理","aria-label":"Permalink to “將 Tuleap 用於軟件項目管理”"},"​")],-1)),t[25]||(t[25]=p("blockquote",null,[p("p",null,"Tuleap 正在被 Eclipse 基金會使用，用來取代 Bugzilla")],-1)),t[26]||(t[26]=p("p",null,[p("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/education/rh_003588_01_rd3os.combacktoschoolseriesk12_rh_021x_0.png?itok=kOixOaEU",alt:"Get to know Tuleap for project management",title:"Get to know Tuleap for project management"})],-1)),t[27]||(t[27]=p("p",null,"圖片提供：opensource.com",-1)),p("p",null,[t[2]||(t[2]=e("Tuleap 是一個獨特的開源項目管理工具，目前發展勢頭很好，現在，每個月它會出一個大版本。它還被列在 ",-1)),o(l,{href:"https://opensource.com/business/15/1/top-project-management-tools-2015"},{default:n(()=>[...t[0]||(t[0]=[e("2015 年五大開源項目管理工具",-1)])]),_:1}),t[3]||(t[3]=e("和 ",-1)),o(l,{href:"https://opensource.com/business/16/3/top-project-management-tools-2016"},{default:n(()=>[...t[1]||(t[1]=[e("2016 年十一個名列前茅項目管理工具",-1)])]),_:1}),t[4]||(t[4]=e("中。",-1))]),t[28]||(t[28]=r("<p>Manuel Vacelet 是開發 Tuleap 項目的 Enalean 公司的聯合創始人和 CTO，他説：“Tuleap 是一個完整用於託管軟件項目的 GPLv2 平台，它提供了一個集中化的平台，在這裏,團隊可以找到他們所需的所有工具，追蹤他們軟件項目的生命週期。他們可以找到項目管理（Scrum、看板、瀑布、混合等等）、源碼控制（git 和 svn）和代碼審查（pull 請求和 gerrit）、持續集成、問題跟蹤、wiki 和文檔等的支持。”</p><p>在這次採訪中，我會和 Manuel 討論如何開始使用它，以及如何以開源方式管理 Tuleap。</p><p>**Nitish Tiwari（以下簡稱 NT）： 為什麼 Tuleap 項目很重要？ **</p><p><strong>Manuel Vacelet（以下簡稱 MV）：</strong> Tuleap 很重要是因為我們堅信一個成功的（軟件）項目必須涉及所有利益相關者：開發人員、項目經理、QA、客户和用户。</p><p>很久以前，我還是一個 SourceForge 衍生項目的實習生（當時 SourceForge 還是一個自由開源項目），幾年後它變成了 Tuleap。 我的第一個貢獻是將 PhpWiki 集成到該工具中（不要告訴任何人，代碼寫的很糟）。</p><p>現在，我很高興作為首席技術官和產品負責人在 Enalean 工作，該公司是 Tuleap 項目的主要貢獻公司。</p><p><strong>NT：讓我們聊聊技術方面。</strong></p><p><strong>MV：</strong> Tuleap 核心系統是基於 LAMP 並且架構於 CentOS 之上。如今的開發棧是 AngularJS (v1)、REST 後端（PHP）、基於 NodeJS 的實時推送服務器。但如果你想成為一名 Tuleap 全棧開發人員，你還將需要接觸 bash、Perl、Python、Docker、Make 等等。</p><p>説到技術方面，需要重點強調的 Tuleap 的一個顯著特徵是它的可擴展性。一個運行在單服務器上的 Tuleap 單一實例、並且沒有複雜的 IT 架構，可以處理超過 10000 人的訪問。</p><p><strong>NT：給我們説下該項目的用户和社區。有誰參與？他們如何使用這個工具？</strong></p><p><strong>MV：</strong> 用户非常多樣化。從使用 Tuleap 跟蹤他們的項目進度並管理他們的源代碼的小型初創公司，到非常大的公司，如法國電信運營商 Orange，它為超過 17000 用户部署了它，並託管了 5000 個項目。</p><p>許多用户依靠 Tuleap 來促進敏捷項目並跟蹤其進度。開發人員和客户共享同一個工作區。客户不需要學習如何使用 GitHub，也不需要開發人員做額外的工作，就可以將其工作轉換到“客户可訪問”平台。</p>",12)),p("p",null,[t[6]||(t[6]=e("今年，Tuleap 被 ",-1)),o(l,{href:"http://www.eclipse.org/"},{default:n(()=>[...t[5]||(t[5]=[e("Eclipse 基金會",-1)])]),_:1}),t[7]||(t[7]=e("所使用，取代了 Bugzilla。",-1))]),t[29]||(t[29]=r("<p>印度電子信息技術部使用 Tuleap 創建了印度政府開放電子政務的開放式協作開發平台。</p><p>Tuleap 有多種不同的使用方式和配置。有些人使用它作為 Drupal 客户門户網站的後端; 它們通過 REST API 插入到 Tuleap 中以管理 bug 和服務請求。</p><p>甚至一些建築師也使用它來管理他們的工作進度和 AutoCAD 文件。</p><p><strong>NT：Tuleap 是否做了一些特別的事，使社區更安全，更多樣化？</strong></p><p><strong>MV：</strong> 我們還沒有創建“行為準則”；本社區非常平和而歡迎新人，但我們有計劃這樣做。Tuleap 的開發人員和貢獻者來自不同的國家（例如加拿大、突尼斯、法國）。而且 35％ 的活躍開發者和貢獻者是女性。</p><p><strong>NT：由社區提議的 Tuleap 功能的百分比是多少？</strong></p><p><strong>MV：</strong> 幾乎 100％ 的功能是由社區驅動的。</p>",7)),p("p",null,[t[9]||(t[9]=e("這是 Enalean 的關鍵挑戰之一：找到一種商業模式，使我們能以正確的方式做開源軟件。對我們來説，“開放核心”模式（其中應用程序的核心是開放的，但有趣和有用的部分是封閉源的）不是正確的方法，因為你最終還是要依賴閉源。因此，我們發明了 ",-1)),o(l,{href:"https://blog.enalean.com/enalean-open-roadmap-how-it-works/"},{default:n(()=>[...t[8]||(t[8]=[e("OpenRoadmap",-1)])]),_:1}),t[10]||(t[10]=e("，這種方式是我們從社區和最終用户那裏收集需求，並找公司來為此買單。",-1))]),t[30]||(t[30]=p("hr",null,null,-1)),t[31]||(t[31]=p("p",null,"作者簡介：",-1)),t[32]||(t[32]=p("p",null,[p("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/nitish-crop.png?itok=h4PaLDQq",alt:""})],-1)),t[33]||(t[33]=p("p",null,"Nitish 是一名專業的軟件開發人員並對開源有熱情。作為一本基於 Linux 的雜誌的技術作者，他會嘗試新的開源工具。他喜歡閲讀和探索任何開源相關的事情。在他的空閒時間，他喜歡讀勵志書。他目前正在構建 DevUp - 一個讓開發人員以真正的方式連接所有工具和擁抱 DevOps 的平台。你可以在 Twitter 上關注他 @tiwari_nitish。",-1)),t[34]||(t[34]=p("hr",null,null,-1)),p("p",null,[t[12]||(t[12]=e("via: ",-1)),o(l,{href:"https://opensource.com/article/17/1/interview-Tuleap-project"},{default:n(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/17/1/interview-Tuleap-project",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=e("作者：",-1)),o(l,{href:"https://opensource.com/users/tiwarinitish86"},{default:n(()=>[...t[13]||(t[13]=[e("Nitish Tiwari",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),o(l,{href:"https://github.com/geeki"},{default:n(()=>[...t[14]||(t[14]=[e("geekpi",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),o(l,{href:"https://github.com/jasminepeng"},{default:n(()=>[...t[15]||(t[15]=[e("jamsinepeng",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const S=s(T,[["render",m]]);export{N as __pageData,S as default};
